type Project={id:string;name:string;province:string;municipality:string;contractor:string;programme:string;status:string;healthScore:number;confidence:number;budget:number;expenditure:number;physicalProgress:number;plannedProgress:number;unitsPlanned:number;unitsCompleted:number;overdueMilestones:number;openRisks:number;evidenceAgeDays:number;forecastCompletion:string;primaryBlocker:string;trend:string;rootCauses:string[];projectManager:string;implementingAgent:string;ward:string;stage:string;startDate:string;recoveryActions:any[];activity:any[]};
